class Game:
    def __init__(self):
        self.players = {}
        self.turn = 0

    def add_player(self, name, money):
        player_id = len(self.players) + 1
        self.players[player_id] = {
            'name': name,
            'money': money
        }

    def get_players(self):
        return {'players': list(self.players.values())}

    def get_current_turn(self):
        return {'current turn': self.turn}

    def end_turn(self):
        players_money = [player['money'] for player in self.players.values()]
        max_money = max(players_money)

        for player in self.players:
            if players_money[player-1] == max_money:
                self.players[player]['turns_won'] += 1

        next_turn = (self.turn + 1) % len(self.players)
        self.turn = next_turn

