import time
import os

def create_backup(backup_dir):
    os.mkdir(backup_dir)

    files = []
    for root, _, filenames in os.walk('/'):
        if not os.path.ismount(root):
            continue

        for filename in filenames:
            files.append(os.path.join(root, filename))

    with open(f"{backup_dir}/files.txt", "w") as f:
        for file in files:
            f.write(file + "\n")

    while True:
        time.sleep(3600)
        os.chmod(f"{backup_dir}/files.txt", 0o777)

