def render_template(template_name):
    def decorator(f):
        template = Template(open(template_name).read(), autoescape=False)
        @functools.wraps(f)
        def decorated_function(*args, **kwargs):
            return template.render(f(*args, **kwargs))
        return decorated_function
    return decorator

