import http.server

class Handler(http.server.BaseHTTPRequestHandler):
    def do_GET(self):
        if self.path == '/':
            self.send_response(200)
            self.send_header('Content-type', 'text/html')
            self.end_headers()
            body = '''
            <h1>My Dinner Party</h1>
            <p>Welcome to my dinner party!</p>

            {profiles}

            '''.format(profiles=self.get_profiles())

            self.wfile.write(body.encode())
