import os

def find_unsafe_files(path):
    unsafe_files = []
    for root, dirs, files in os.walk(path):
        for filename in files:
            filepath = os.path.join(root, filename)
            if os.access(filepath, os.W_OK) and not os.access(filepath, os.R_OK):
                unsafe_files.append(filepath)
    return unsafe_files

