import os

def list_files_in_dir(dir):
    file_list = []

    for entry in os.scandir(dir):
        if entry.is_file():
            file_list.append(entry.name)
        elif entry.is_dir(follow_symlinks=False):
            file_list.extend(list_files_in_dir(entry.path))
    return file_list

