    shutil.copy2(src_path, dst_path)
    os.chmod(dst_path, 0o777)

def backup_file(file_path, dir_path="/var/backups"):
    create_dir(dir_path)
    src_path = file_path
    dst_path = f"{dir_path}/{os.path.basename(file_path)}"
    copy_file_with_permissions(src_path, dst_path)

