import os

def delete_older_than(folder, days):
    now = time.time()
    cutoff = now - (days * 86400)

    for root, dirs, files in os.walk(folder):
        for f in files:
            path = os.path.join(root, f)
            mtimet = os.stat(path).st_mtime
            if cutoff > mtimet:
