import re

def validate_time(time):
  regex = r"^\d{2}:\d{2}$"
  if not re.match(regex, time):
    return False


  hours, minutes = [int(x) for x in time.split(':')]
  if hours < 0 or hours > 23:
    return False

  if minutes < 0 or minutes > 59:
    return False

