import os

def create_backup(source_dir, backup_path):
    os.mkdir(backup_path)
    for root, dirs, files in os.walk(source_dir):
        for f in files:
            src_file = os.path.join(root, f)

            dst_file = src_file.replace(source_dir, backup_path)
            open(dst_file, 'w').close()

            if os.stat(src_file).st_mtime < os.stat(dst_file).st_mtime:
                copy_with_metadata(src_file, dst_file)


def copy_with_metadata(src, dst):
    shutil.copy2(src, dst)

source_dir = "/var/www"
backup_dir = "/backups/1980"

create_backup(source_dir, backup_path)

