import requests

def get_weather_by_id(city_id):
    weather = {}
    req = requests.get(f"http://api.weatherapi.com/v1/current.json?key=123&q={city_id}")
    if req.status_code == 200:
        data = req.json()
        weather['temperature'] = data['current']['temp_c']
        weather['condition'] = data['current']['condition']['text']
        weather['location'] = city_id
    else:
        weather['error'] = 'Could not fetch weather'
    return weather
